package com.bank.payments.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class PayOrderServiceTest {

    private static final long ACCOUNT_NUMBER = 100200L;
    private static final long MOVEMENT = 9000000001L;

    record Update(Long accountNumber, BigDecimal balance) {
    }

    record Mark(Integer orderNumber, Integer companyId, Long movementNumber, BigDecimal commission) {
    }

    /** In-memory fakes of the three ports, recording every call in order. */
    private static final class World {
        final List<String> events = new ArrayList<>();
        final List<Update> updates = new ArrayList<>();
        final List<Mark> marks = new ArrayList<>();
        final List<Integer> movementOrders = new ArrayList<>();
        final List<Integer> readOrderNumbers = new ArrayList<>();
        final List<Integer> readCompanies = new ArrayList<>();
        final List<Long> readAccounts = new ArrayList<>();

        Optional<PaymentOrder> order = Optional.of(order("P", "1000.00"));
        Optional<Account> account = Optional.of(account("CTE", "5000.00", "A"));
        long movement = MOVEMENT;

        final OrderRepository orders = new OrderRepository() {
            @Override
            public Optional<PaymentOrder> findByKeyForUpdate(Integer orderNumber, Integer companyId) {
                events.add("order.read");
                readOrderNumbers.add(orderNumber);
                readCompanies.add(companyId);
                return order;
            }

            @Override
            public int markPaid(Integer orderNumber, Integer companyId, Long movementNumber, BigDecimal commission) {
                events.add("order.markPaid");
                marks.add(new Mark(orderNumber, companyId, movementNumber, commission));
                return 1;
            }
        };

        final AccountRepository accounts = new AccountRepository() {
            @Override
            public Optional<Account> findByNumberForUpdate(Long accountNumber) {
                events.add("account.read");
                readAccounts.add(accountNumber);
                return account;
            }

            @Override
            public int updateBalance(Long accountNumber, BigDecimal balance) {
                events.add("account.update");
                updates.add(new Update(accountNumber, balance));
                return 1;
            }
        };

        final MovementGateway movements = orderNumber -> {
            events.add("movement.register");
            movementOrders.add(orderNumber);
            return movement;
        };

        PayOrderService service() {
            return new PayOrderService(orders, accounts, movements);
        }
    }

    private static PaymentOrder order(String status, String value) {
        return new PaymentOrder(1234567, 10, status, new BigDecimal(value), null, null);
    }

    private static Account account(String type, String balance, String status) {
        return new Account(ACCOUNT_NUMBER, type, new BigDecimal(balance), status);
    }

    private static PayOrderRequest req(String orderNumber, String accountType, String channel, String key,
            String value) {
        return new PayOrderRequest(orderNumber, 10, accountType, ACCOUNT_NUMBER, new BigDecimal(value), channel, key);
    }

    private static PayOrderRequest validWeb() {
        return req("1234567", "CTE", "WEB", "      ", "1000.00");
    }

    private static void assertRejected(World w, PayOrderRequest request, String code, String message) {
        assertThatThrownBy(() -> w.service().execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError b = (BusinessError) e;
                    assertThat(b.code()).isEqualTo(code);
                    assertThat(b.legacyCode()).isEqualTo("-1");
                    assertThat(b.getMessage()).isEqualTo(message);
                });
        assertNoWrites(w);
    }

    private static void assertNoWrites(World w) {
        assertThat(w.updates).isEmpty();
        assertThat(w.marks).isEmpty();
        assertThat(w.movementOrders).isEmpty();
    }

    // ---------- RULE-018 / RULE-016 / RULE-017: success paths ----------

    @Test
    void successful_payment_web_marks_order_paid_with_movement_and_commission() {
        World w = new World();

        PayOrderResponse r = w.service().execute(validWeb());

        assertThat(r.orderNumber()).isEqualTo(1234567);
        assertThat(r.commission()).isEqualByComparingTo("1.00");
        assertThat(r.movementNumber()).isEqualTo(9000000001L);
        assertThat(r.resultMessage()).isEqualTo("PAGO REALIZADO");
        assertThat(w.marks).hasSize(1);
        Mark m = w.marks.get(0);
        assertThat(m.orderNumber()).isEqualTo(1234567);
        assertThat(m.companyId()).isEqualTo(10);
        assertThat(m.movementNumber()).isEqualTo(9000000001L);
        assertThat(m.commission()).isEqualByComparingTo("1.00");
        assertThat(w.movementOrders).containsExactly(1234567);
    }

    @Test
    void successful_payment_debits_value_plus_commission_web() {
        World w = new World();

        w.service().execute(validWeb());

        assertThat(w.updates).hasSize(1);
        assertThat(w.updates.get(0).accountNumber()).isEqualTo(ACCOUNT_NUMBER);
        assertThat(w.updates.get(0).balance()).isEqualByComparingTo("3999.00");
    }

    @Test
    void successful_payment_office_commission_2_50_total_1002_50() {
        World w = new World();

        PayOrderResponse r = w.service().execute(req("1234567", "CTE", "OFI", "ABC123", "1000.00"));

        assertThat(r.commission()).isEqualByComparingTo("2.50");
        assertThat(w.updates.get(0).balance()).isEqualByComparingTo("3997.50");
        assertThat(w.marks.get(0).commission()).isEqualByComparingTo("2.50");
